const items = $input.all();

return items.map(item => {
  const path = item.json.attachments;

  let type = "UNKNOWN";

  if (path.toLowerCase().includes("_si.")) {
    type = "SI";
  } else if (path.toLowerCase().includes("_bl.")) {
    type = "BL";
  }

  return {
    json: {
      email_id: item.json.email_id,
      attachment_path: path,
      document_type: type
    }
  };
});

const docs = $input.all();
const identified = $('Identify Attachment').all();

return docs.map((doc, index) => {
  return {
    json: {
      email_id: identified[index].json.email_id,
      document_type: identified[index].json.document_type,
      attachment_path: identified[index].json.attachment_path,
      document_text: doc.json.data
    }
  };
});

const extracted = $input.all();
const sourceDocs = $('Prepare Document').all();

// Group documents by email_id
const grouped = {};

for (let i = 0; i < extracted.length; i++) {
  const source = sourceDocs[i]?.json;

  if (!source) continue;

  const emailId = source.email_id;
  const type = source.document_type;
  const data = extracted[i].json.output ?? extracted[i].json;

  if (!grouped[emailId]) {
    grouped[emailId] = {};
  }

  grouped[emailId][type] = data;
}

// Fields that must be compared
const fields = [
  "shipper",
  "consignee",
  "notify_party",
  "port_of_loading",
  "port_of_discharge",
  "container_count",
  "gross_weight_kg"
];

function normalizeText(value) {
  if (value === null || value === undefined) {
    return "";
  }

  return String(value)
    .trim()
    .toUpperCase()
    .replace(/\s+/g, " ")
    .replace(/[.,]/g, "");
}

// Produce ONE result per email
const results = [];

for (const [emailId, docs] of Object.entries(grouped)) {

  const si = docs.SI;
  const bl = docs.BL;

  // Missing SI or BL
  if (!si || !bl) {
    results.push({
      json: {
        email_id: emailId,
        status: "NEEDS_REVIEW",
        review_reason: "missing_attachment",
        has_defect: false,
        defect_fields: []
      }
    });

    continue;
  }

  const defectFields = [];

  for (const field of fields) {

    const siValue = si[field];
    const blValue = bl[field];

    if (
      field === "container_count" ||
      field === "gross_weight_kg"
    ) {
      if (Number(siValue) !== Number(blValue)) {
        defectFields.push(field);
      }
    } else {
      if (normalizeText(siValue) !== normalizeText(blValue)) {
        defectFields.push(field);
      }
    }
  }

  const hasDefect = defectFields.length > 0;

  results.push({
    json: {
      email_id: emailId,
      status: hasDefect ? "MISMATCH" : "OK",
      review_reason: null,
      has_defect: hasDefect,
      defect_fields: defectFields,

      // Keep temporarily for debugging
      si_extracted: si,
      bl_extracted: bl
    }
  });
}

return results;

const items = $input.all();

return items.map(item => {
  return {
    json: {
      email_id: item.json.email_id,
      category: "BL_COMPARISON",
      status: item.json.status,
      review_reason: item.json.review_reason ?? null,
      has_defect: item.json.has_defect ?? false,
      defect_fields: item.json.defect_fields ?? []
    }
  };
});

return {
  json: {
    email_id: $json.email_id,
    category: $json.category,
    status: "OK",
    review_reason: null,
    has_defect: false,
    defect_fields: []
  }
};

return {
  json: {
    email_id: $json.email_id,
    category: "BL_COMPARISON",
    status: "NEEDS_REVIEW",
    review_reason: "missing_attachment",
    has_defect: false,
    defect_fields: []
  }
};

return {
  json: {
    email_id: $json.email_id,
    subject: $json.subject,
    body: $json.body,
    attachments: $json.attachments ?? []
  }
};

const email = $('Prepare Email').item.json;
const ai = $json.output;

return {
  json: {
    email_id: email.email_id,
    subject: email.subject,
    body: email.body,
    attachments: email.attachments ?? [],
    category: ai.category,
    confidence: ai.confidence
  }
};
